def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker_col = next(c for row in grid for c, v in enumerate(row) if v == 5) - 8
    x = max(0, min(6, marker_col))
    out[0][x] = 5
    y = 0

    # Read the symbols down the left side, then down the right side.
    symbols = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            colors = [grid[r][c]
                      for r in range(top, top + 3)
                      for c in range(left, left + 3)
                      if grid[r][c] != 0 and grid[r][c] != 4 and grid[r][c] != 5]
            if colors:
                symbols.append(colors[0])

    for color in symbols:
        if color == 6:
            for _ in range(2):
                y += 1
                if y < h:
                    out[y][x] = 6
        else:
            length = {1: 3, 2: 2, 3: 4}[color]
            direction = 1 if color == 1 else -1
            y += 1
            for _ in range(length):
                if y < h and 0 <= x < 7:
                    out[y][x] = color
                x += direction
            x -= direction
            x = max(0, min(6, x))

        if y >= h:
            break

    return out
